IExecutionAsyncWaiter::IExecutionAsyncWaiter(
    IExecution* proxy) : proxy_(proxy) {}

IExecutionAsyncWaiter::~IExecutionAsyncWaiter() = default;

void IExecutionAsyncWaiter::compute(
    absl::optional<android::nn::TimePoint> deadline, android::nn::ExecutionError* out_executionError, std::vector<android::nn::OutputShape>* out_outputShape, android::nn::Timing* out_timing) {
  base::RunLoop loop;
  proxy_->compute(std::move(deadline),
      base::BindOnce(
          [](base::RunLoop* loop,
             android::nn::ExecutionError* out_executionError
,
             std::vector<android::nn::OutputShape>* out_outputShape
,
             android::nn::Timing* out_timing
,
             android::nn::ExecutionError executionError,
             const std::vector<android::nn::OutputShape>& outputShape,
             android::nn::Timing timing) {*out_executionError = std::move(executionError);*out_outputShape = std::move(outputShape);*out_timing = std::move(timing);
            loop->Quit();
          },
          &loop,
          out_executionError,
          out_outputShape,
          out_timing));
  loop.Run();
}



void IExecutionAsyncWaiter::computeFenced(
    std::vector<android::nn::SyncFence> waitFor, absl::optional<android::nn::TimePoint> deadline, absl::optional<android::nn::Duration> timeoutDurationAfterFence, android::nn::GeneralError* out_status, absl::optional<android::nn::SyncFence>* out_syncFence, ::mojo::PendingRemote<::chromeos::nnapi::canonical::mojom::IExecuteFencedInfoCallback>* out_executionCallback) {
  base::RunLoop loop;
  proxy_->computeFenced(std::move(waitFor),std::move(deadline),std::move(timeoutDurationAfterFence),
      base::BindOnce(
          [](base::RunLoop* loop,
             android::nn::GeneralError* out_status
,
             absl::optional<android::nn::SyncFence>* out_syncFence
,
             ::mojo::PendingRemote<::chromeos::nnapi::canonical::mojom::IExecuteFencedInfoCallback>* out_executionCallback
,
             android::nn::GeneralError status,
             absl::optional<android::nn::SyncFence> syncFence,
             ::mojo::PendingRemote<::chromeos::nnapi::canonical::mojom::IExecuteFencedInfoCallback> executionCallback) {*out_status = std::move(status);*out_syncFence = std::move(syncFence);*out_executionCallback = std::move(executionCallback);
            loop->Quit();
          },
          &loop,
          out_status,
          out_syncFence,
          out_executionCallback));
  loop.Run();
}








